<?php $p = row("SELECT p.*, e.name, e.national_id, e.position FROM payslips p JOIN employees e ON e.id=p.employee_id WHERE p.id=?", [req_int('id')]); if (!$p) exit('یافت نشد'); $items = json_decode($p['items'], true) ?: []; ?>
<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>فیش حقوق</title><link rel="stylesheet" href="assets/print.css"><style>@page{size:A5;margin:8mm}</style></head><body class="pp"><section class="a4" style="min-height:auto;width:auto">
<header class="dh"><b><?= h(setting('biz_name')) ?></b><h1>فیشِ حقوقِ <?= h(fa_num(str_replace('-', '/', $p['ym']))) ?></h1><div class="meta"><?= h($p['name']) ?><br><?= h($p['position']) ?></div></header>
<table class="lines"><tr><th>مزایا</th><th>مبلغ</th><th>کسورات</th><th>مبلغ</th></tr><?php $e = array_values(array_filter($items, fn($i) => $i['k'] === 'earn')); $d = array_values(array_filter($items, fn($i) => $i['k'] === 'ded'));
for ($i = 0; $i < max(count($e), count($d)); $i++): ?><tr><td class="t"><?= h($e[$i]['t'] ?? '') ?></td><td><?= isset($e[$i]) ? fa_money($e[$i]['a']) : '' ?></td><td class="t"><?= h($d[$i]['t'] ?? '') ?></td><td><?= isset($d[$i]) ? fa_money($d[$i]['a']) : '' ?></td></tr><?php endfor; ?>
<tr class="carry"><td>جمعِ مزایا</td><td><?= fa_money($p['gross']) ?></td><td>جمعِ کسورات</td><td><?= fa_money($p['deductions']) ?></td></tr></table><p style="font-size:13pt">خالصِ پرداختی: <b><?= fa_rial($p['net']) ?></b> — <?= h(money_words((int)$p['net'])) ?></p></section><script>setTimeout(function(){print()},300)</script></body></html>
